#define LOOP(i, start, end) for (int i = start; i <= end; i++)
#define REVERSE_LOOP(i, start, end) for (int i = start; i >= end; i--)

const int MAX_SIZE = 1e6 + 1e5, MOD_CONST = 1e9 + 7;

LL base, modulus;
int total;
LL result;
int visited[MAX_SIZE];
int values[MAX_SIZE];

void normalize(LL &x) { x = (x % MOD_CONST + MOD_CONST) % MOD_CONST; }

void explore(int x)
{
    ++total;
    int initial = x;
    LL weight = 1;
    do {
        visited[x] = true;
        x = x * base % modulus;
        weight = weight * base % modulus;
    } while (x != initial);
    normalize(result *= (weight == 1 ? modulus : 1));
}

void compute()
{
    if (base == 0) {
        LL prod = 1;
        LOOP(i, 1, modulus - 1)
            prod = prod * modulus % MOD_CONST;
        printf("%lld\n", prod);
        return;
    }
    result = 1;
    LOOP(i, 0, modulus - 1)
        if (visited[i] == 0)
            explore(i);
    printf("%lld\n", result);
